/* Error panel */
.rp-inline-runner-content .rp-error-panel {
  background: var(--background-modifier-error);
  border-radius: var(--radius-s);
  padding: var(--size-4-3);
}

.rp-inline-runner-content .rp-error-title {
  font-weight: var(--font-semibold);
  color: var(--text-error);
  margin: 0 0 var(--size-4-2) 0;
}

.rp-inline-runner-content .rp-error-list {
  margin: 0;
  padding-left: var(--size-4-4);
}

/* Phase 75: runner footer row (Back/Skip) */
.rp-runner-footer-row {
  display: flex;
  gap: var(--size-4-2);
  justify-content: flex-end;
}

/* Phase 75: complete heading */
.rp-complete-heading {
  font-size: var(--font-ui-medium);
  font-weight: var(--font-semibold);
  margin: 0 0 var(--size-4-2) 0;
}

/* Icon buttons (Back/Skip/Close) */
.rp-runner-icon-btn {
  width: 28px;
  height: 28px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-s);
  background: transparent;
  border: 1px solid var(--background-modifier-border);
  color: var(--text-muted);
  cursor: pointer;
  flex-shrink: 0;
}

.rp-runner-icon-btn:hover {
  background: var(--background-modifier-hover);
  color: var(--text-normal);
}

.rp-runner-icon-btn svg {
  width: 14px;
  height: 14px;
}

.rp-inline-runner-container.rp-state-content-only .rp-inline-runner-content > .rp-runner-footer-row {
  flex: 0 0 auto;
  margin-top: var(--size-2-3);
}

/* Self-check */
.rp-inline-runner-self-check {
  display: flex;
  flex-direction: column;
  gap: var(--size-2-2);
}

.rp-inline-runner-self-check-item {
  display: flex;
  align-items: flex-start;
  gap: var(--size-2-2);
  line-height: 1.4;
}

/* Phase 2 — footer left group: close + create-snippet-from-selection, pushed to the
   space-between row's start side (Back/Redo/Skip group stays on the end side). */
.rp-runner-footer-left {
  display: flex;
  align-items: center;
  gap: var(--size-4-2);
  justify-content: flex-start;
}

/* Phase 2 — disabled icon buttons read as inactive. Additive: also styles the
   Back/Redo/Skip buttons' disabled state set via .disabled = true in renderFooterIcons. */
.rp-runner-icon-btn:disabled,
.rp-runner-icon-btn:disabled:hover {
  opacity: 0.4;
  cursor: not-allowed;
  background: transparent;
  color: var(--text-muted);
}

